from produire import produire
from format_lecon import paras,table,steps
from medicaments import antalgie,amoxicilline

p=[
('La {pharyngite virale aiguë} est une inflammation pharyngée causée par un virus. Elle accompagne souvent une infection respiratoire. Le diagnostic de forme simple suppose une évaluation de la gravité.',paras('Les virus respiratoires cités par Pédiatrie suisse comprennent rhinovirus, coronavirus et adénovirus. Une toux ou une rhinorrhée associée rend cette hypothèse plausible, mais ne permet pas d’identifier le virus.', 'L’amygdalite désigne l’atteinte amygdalienne ; un exsudat peut exister dans une maladie virale. La mononucléose est développée séparément car son bilan et ses précautions diffèrent.')),
('Les {causes virales sont les plus fréquentes}. Le contage et les symptômes respiratoires orientent. Une évolution qui s’aggrave exige une réévaluation.',paras('La synthèse de Pédiatrie suisse 2023 décrit les virus comme causes majoritaires des pharyngites. La fréquence dépend de l’âge, de la saison et de la population étudiée ; aucune incidence suisse unique par virus n’est fournie ici.', 'NICE indique que la plupart des maux de gorge aigus s’améliorent en environ une semaine, avec ou sans antibiotique. Ce délai décrit une évolution habituelle et ne justifie pas d’attendre devant une alarme.')),
('L’{inflammation muqueuse explique douleur et rougeur}. La réponse inflammatoire rend la déglutition douloureuse. Le traitement de soutien vise le retentissement de cette inflammation.',table(['Perturbation','Comment l’évaluer','Réponse'],[['Inflammation de la muqueuse.','Rougeur, douleur et signes respiratoires à l’examen.','Antalgie compatible avec le terrain.'],['Apports réduits par la douleur.','Interroger sur boissons, diurèse et signes de déshydratation.','Boissons fractionnées ; assistance médicale si les apports échouent.'],['Atteinte dépassant le tableau de surface.','Chercher stridor, trismus, asymétrie ou altération générale.','Réorienter le diagnostic ; ne pas augmenter simplement l’antalgique.']])+paras('La gorge est un carrefour respiratoire et digestif. L’impossibilité d’avaler la salive ou un effort respiratoire ne correspond pas à une simple mesure d’intensité de la douleur : ces signes changent la sécurité du parcours.')),
('Les {diagnostics graves sont exclus avant de retenir une virose simple}. Un test streptococcique négatif ne suffit pas. Les signes focaux ou respiratoires imposent un autre bilan.',table(['Hypothèse','Discriminant','Conduite'],[['🚩 Épiglottite.','Douleur intense, salivation, voix étouffée ou stridor.','Urgence respiratoire et examen sécurisé.'],['🚩 Abcès périamygdalien.','Trismus, asymétrie et bombement du voile.','Avis ORL urgent.'],['Angine à streptocoque.','Tableau compatible et test utile selon Centor/terrain.','Décision antibiotique sélective.'],['Mononucléose.','Fatigue marquée, ganglions diffus et éventuelle splénomégalie.','Sérologie selon contexte ; protéger la rate.']])) ,
('L’{anamnèse précise le tableau respiratoire et son évolution}. Demander toux, rhinorrhée, contage et capacité à boire. Une aggravation rapide ou une reprise fébrile change l’hypothèse.',paras('Préciser le début de la douleur et son caractère bilatéral ou focal. Une toux, un enrouement et des aphtes orientent vers une origine virale selon Pédiatrie suisse, sans valeur de preuve absolue.', 'Rechercher immunosuppression, âge extrême, antécédents de rhumatisme articulaire aigu, exposition sexuelle pertinente et médicaments récents. Une plainte attribuée à un virus ne dispense pas d’une anamnèse adaptée.')),
('L’{examen cherche une inflammation simple et une hydratation conservée}. Une voix et une respiration confortables sont attendues. Examiner les amygdales et le cou sans forcer si une obstruction est suspectée.',paras('Chez le patient stable, inspecter les deux côtés de l’oropharynx et rechercher ulcérations, exsudats, asymétrie ou déviation de la luette. Palper doucement les aires ganglionnaires et vérifier l’ouverture buccale.', 'Évaluer l’état général et l’aptitude à boire. Une douleur disproportionnée, un trismus ou un torticolis requiert un avis, même si le fond de gorge est peu spectaculaire.')),
('L’{approche syndromique associe gorge et signes extra-pharyngés}. Le contexte respiratoire appuie l’hypothèse virale. Un syndrome systémique ou focal impose de l’élargir.',paras('<em>7.1 — Syndrome respiratoire de surface.</em> Toux, rhinorrhée et enrouement sont recherchés à l’interrogatoire et à l’écoute de la voix. Ils reflètent une atteinte des voies respiratoires supérieures.', '<em>7.2 — Syndrome mononucléosique.</em> Une asthénie importante et des adénopathies diffuses conduisent à rechercher une infection EBV ou une autre cause.', '<em>7.3 — Syndrome obstructif ou suppuratif.</em> Salivation, stridor, trismus ou tuméfaction unilatérale exigent un changement immédiat de parcours.')),
('Le {diagnostic reste clinique dans une forme simple}. Aucune couleur de gorge n’est spécifique d’un virus. Une étiologie précise n’est recherchée que si elle modifie les mesures utiles.',paras('Il n’existe pas ici de test unique confirmant toutes les pharyngites virales. L’association de signes respiratoires, d’un examen non compliqué et d’une évolution compatible permet une hypothèse clinique.', 'Ne pas appeler automatiquement viral tout résultat streptococcique négatif. Si les symptômes persistent ou s’aggravent, reconsidérer les infections profondes, la mononucléose, les expositions sexuelles et les causes non infectieuses.')),
('Les {examens sont limités dans une forme non compliquée}. Un bilan sanguin systématique ne distingue pas utilement tous les virus. Les prélèvements ciblés répondent à une question clinique.',table(['Étape','Décision'],[['9.a : clinique simple.','Pas de bilan systématique après tri satisfaisant.'],['9.b : streptocoque plausible.','Test rapide seulement s’il influence le choix thérapeutique selon la démarche suisse.'],['9.c : terrain ou exposition.','Examens dirigés vers EBV, VIH ou autres agents selon l’anamnèse.'],['9.d : complication.','Imagerie, cultures ou avis hospitalier selon les signes, sans attendre un résultat viral.']])) ,
('L’{algorithme privilégie le soutien et la surveillance}. Une forme simple ne justifie pas un antibiotique. Une évolution atypique impose un nouvel examen.',steps('Écarter obstruction, déshydratation importante et infection profonde.','Si tableau simple compatible, expliquer l’évolution habituelle et commencer le soutien.','Tester une étiologie uniquement si le résultat change la conduite.','Donner les signes de retour immédiat et organiser le contrôle selon terrain.','Réexaminer si absence d’amélioration attendue ou aggravation.')),
('La {prise en charge repose sur hydratation et antalgie}. Les antibiotiques n’agissent pas sur les virus. Le traitement choisi doit rester sûr pour l’âge et les comorbidités.',paras('<em>11.A — Sécurité.</em> Un patient qui n’avale plus ou respire difficilement nécessite une évaluation urgente.', '<em>11.B — Symptômes.</em> Proposer des boissons fractionnées et une alimentation tolérée. @@MEDICAMENTS@@', '<em>11.C — Étiologie.</em> Pas d’antibiotique pour une virose simple. Un traitement antiviral éventuel répond à une infection identifiée et à une indication spécifique, pas au seul symptôme de gorge.', '<em>11.D — Surveillance.</em> Revenir sans délai si dyspnée, salivation, trismus, confusion ou incapacité à boire. Réévaluer une plainte qui ne commence pas à s’améliorer dans le délai attendu.')),
('La {prévention limite les échanges de sécrétions}. Se laver les mains et ne pas partager les objets portés à la bouche sont des mesures simples. Les consignes spécifiques dépendent de l’agent éventuellement identifié.',paras('Expliquer que l’antibiotique n’empêche pas la transmission d’un virus. Adapter la reprise des activités à l’état général et aux consignes applicables à l’infection concernée.', 'Une succession de maux de gorge ne prouve pas une récidive de la même infection. Rechercher irritation, reflux ou autre cause si le caractère aigu disparaît.')),
('Le {point clé est de reconnaître une forme simple sans manquer une complication}. Un exsudat et une forte douleur ne prouvent pas un streptocoque. La surveillance est une décision active.',paras('L’information donnée au patient doit préciser ce qui est attendu et ce qui doit alerter. L’absence de prescription antibiotique n’est cohérente que si le tri, le terrain et les conditions de suivi ont été évalués.'))]
q=[('Une pharyngite virale peut-elle avoir un exsudat ?','Oui.'),('Toux et rhinorrhée prouvent-elles le virus ?','Non, elles orientent.'),('Quel germe exclut un test rapide streptococcique négatif ?','Il diminue la probabilité du streptocoque A ; il ne recherche pas tous les agents.'),('Un test négatif exclut-il une épiglottite ?','Non.'),('Quelle évolution habituelle décrit NICE ?','Une amélioration en environ une semaine pour la plupart des maux de gorge aigus.'),('Faut-il attendre une semaine devant un stridor ?','Non, c’est une urgence.'),('Quel objectif du traitement de soutien est essentiel ?','Préserver l’hydratation et soulager la douleur.'),('Un antibiotique empêche-t-il la transmission virale ?','Non.'),('Quand revoir le diagnostic ?','En cas d’aggravation, de persistance ou de signes atypiques.'),('Une asymétrie avec trismus est-elle banale ?','Non, rechercher une suppuration profonde.'),('Le paracétamol convient-il à toute hépatite ?','Non, l’hépatite aiguë est contre-indiquée dans la notice citée.'),('Peut-on additionner plusieurs produits au paracétamol ?','Seulement en comptant la dose totale ; éviter les doublons.'),('Une grande fatigue avec ganglions diffus suggère quoi ?','Notamment une mononucléose.'),('Une simple baisse de douleur prouve-t-elle le diagnostic ?','Non.')]
produire(1,p,q,(1,2,3,4,6,13),antalgie)

p=[
('L’{angine à streptocoque du groupe A} est une infection pharyngo-amygdalienne liée à Streptococcus pyogenes. La clinique seule ne l’affirme pas. Le besoin de traitement dépend aussi du terrain et de l’évolution.',paras('Le terme angine n’indique pas à lui seul une origine bactérienne. La confirmation microbiologique doit être recherchée lorsqu’elle influence la conduite, selon la stratégie suisse.', 'Un portage peut compliquer l’interprétation d’un résultat positif. Le test doit donc rester lié à un tableau clinique compatible ; la prise en charge ne se résume pas à traiter un résultat.')),
('La {fréquence varie avec l’âge}. Le streptocoque A est une cause bactérienne usuelle. Les complications restent au centre du tri malgré leur rareté.',paras('Pédiatrie suisse 2023 rapporte 5–15 % des angines chez l’adulte et 20–30 % chez l’enfant. Ces proportions ne constituent pas un classement chiffré des dix causes du présent cours.', 'L’amélioration spontanée est fréquente. La baisse historique du rhumatisme articulaire aigu en Suisse contribue à la stratégie antibiotique sélective ; un antécédent personnel ou familial impose toutefois une appréciation spécifique.')),
('L’{infection déclenche une inflammation amygdalienne}. La douleur et les ganglions reflètent la réaction locale. Une suppuration ou une complication immunologique suit un autre mécanisme.',table(['Mécanisme','Exploration','Conséquence thérapeutique'],[['Inflammation pharyngo-amygdalienne.','Examen et test rapide si utile.','Soutien ; antibiotique selon indication clinique.'],['Extension purulente.','Trismus, asymétrie, imagerie ou prélèvement du foyer.','Avis urgent et contrôle du foyer.'],['Complication immunologique.','Signes articulaires, cardiaques ou urinaires selon évolution.','Bilan spécifique ; ne pas assimiler à une simple persistance locale.']])+paras('La synthèse suisse indique que l’antibiothérapie ne prévient pas la glomérulonéphrite aiguë post-streptococcique. Ne pas promettre cette prévention pour justifier un traitement systématique.')),
('Le {tri recherche d’abord une infection compliquée}. Une collection ou un sepsis prime sur le score clinique. Une mononucléose peut imiter cette angine et change le choix médicamenteux.',table(['Concurrent','Indice discriminant','Action'],[['🚩 Abcès périamygdalien.','Trismus et asymétrie du voile.','Avis ORL urgent.'],['🚩 Lemierre.','Reprise fébrile, douleur cervicale et signes pulmonaires.','Urgence hospitalière.'],['Mononucléose.','Asthénie, adénopathies diffuses, splénomégalie.','Évaluation ciblée ; éviter l’amoxicilline de la notice citée.'],['Pharyngite virale.','Toux, rhinite ou enrouement.','Soutien selon tableau et tests utiles.']])) ,
('L’{anamnèse recherche les critères cliniques et le terrain}. Préciser fièvre, absence de toux et exposition. Vérifier surtout les antécédents et les possibilités de suivi.',paras('Demander une histoire de rhumatisme articulaire aigu personnelle ou familiale, une immunosuppression et le contexte épidémiologique. Les recommandations pédiatriques suisses prévoient un test quel que soit le score en cas d’antécédent de rhumatisme articulaire aigu.', 'Préciser allergies aux pénicillines, traitements récents, maladie rénale, grossesse et allaitement. Une réaction cutanée ancienne ne doit pas être qualifiée sans détails, mais une allergie grave ne doit jamais être minimisée.')),
('L’{examen documente les signes de Centor sans les surinterpréter}. Inspecter les amygdales et palper les ganglions antérieurs. Comparer les côtés et apprécier l’hydratation.',paras('Les quatre critères sont absence de toux, exsudats amygdaliens, antécédent de fièvre ou température supérieure à 38°C et adénopathie cervicale antérieure sensible. Chaque critère vaut un point dans le score de Centor.', 'Rechercher une éruption compatible avec une scarlatine, mais aussi asymétrie, trismus ou salivation. Une scarlatine mérite une évaluation soigneuse ; les pratiques antibiotiques peuvent différer selon contexte de flambée et facteurs de risque.')),
('L’{approche syndromique distingue angine simple et maladie compliquée}. Un syndrome scarlatiniforme est à reconnaître. Des signes à distance exigent un bilan distinct.',paras('<em>7.1 — Angine simple.</em> Douleur pharyngée, fièvre et inflammation amygdalienne sans obstruction ni suppuration profonde.', '<em>7.2 — Tableau scarlatiniforme.</em> Éruption associée à l’angine, à interpréter avec l’examen et le contexte épidémiologique.', '<em>7.3 — Complication.</em> Trismus, asymétrie, douleur cervicale ou altération générale font rechercher un foyer profond ; symptômes articulaires, cardiaques ou urinaires appellent un autre bilan.')),
('Le {test rapide sert une décision thérapeutique}. Centor estime une probabilité clinique. Un résultat positif ne rend pas l’antibiothérapie obligatoire dans toute forme simple.',paras('La SSI propose de ne pas tester ni traiter aux scores 0–2 dans une angine simple. Aux scores 3–4, le test est envisagé si une antibiothérapie serait retenue en cas de positivité ; chez l’enfant, la directive mentionne un âge supérieur à 3 ans.', 'La synthèse pédiatrique suisse propose, sans critère d’inquiétude, un traitement symptomatique et une réévaluation à 48–72 heures. Les différences d’âge, de terrain et de suivi doivent être prises en compte ; un score ne remplace pas le raisonnement.')),
('Les {examens évitent le dépistage sans conséquence clinique}. Le test rapide est ciblé. La culture n’est pas une confirmation systématique après chaque test négatif.',table(['Étape','Principe'],[['9.a : indication.','Tester si la probabilité et le projet thérapeutique rendent le résultat utile.'],['9.b : prélèvement.','Frottis pharyngé effectué selon la procédure du test ; qualité du prélèvement à vérifier.'],['9.c : résultat négatif.','Pas de culture de rattrapage systématique selon SSI/Pédiatrie suisse ; réévaluer si tableau inquiétant.'],['9.d : complication.','Cultures, hémocultures ou imagerie orientées par le foyer et la gravité, indépendamment du test rapide.']])) ,
('L’{algorithme articule tri, test et suivi}. Une observation documentée est possible. L’aggravation impose un examen avant de simplement commencer une ordonnance en réserve.',steps('Écarter une urgence et évaluer le terrain.','Calculer Centor lorsque le tableau s’y prête.','Décider si le résultat d’un test modifierait le traitement.','Choisir soutien seul, prescription différée organisée ou antibiotique selon indication.','Réévaluer à 48–72 heures selon le parcours pédiatrique, immédiatement si alarme.')),
('La {prise en charge suisse est sélective}. L’antibiothérapie suit une indication explicite et une vérification des contre-indications. Le schéma de la recommandation peut différer de la notice.',paras('<em>11.A — Complication.</em> Une suspicion de collection, de sepsis ou d’obstruction relève de l’hôpital et non du schéma ambulatoire.', '<em>11.B — Forme simple.</em> Antalgie et hydratation, avec information sur le bénéfice limité des antibiotiques et leurs effets indésirables.', '<em>11.C — Antibiotique si indiqué.</em> @@MEDICAMENTS@@', '<em>11.D — Surveillance.</em> Vérifier réponse, tolérance et observance du schéma choisi. Une diarrhée importante, une réaction cutanée ou une aggravation appelle une réévaluation ; ne pas raccourcir ou prolonger arbitrairement le traitement.')),
('La {prévention repose sur l’hygiène et un suivi adapté}. L’éviction scolaire systématique n’est plus la règle suisse décrite en 2023. L’état général et les mesures sanitaires particulières guident la reprise.',paras('Ne pas promettre que l’antibiotique empêchera toute complication ou toute transmission. Expliquer comment joindre le soignant si le tableau change.', 'Une histoire de rhumatisme articulaire aigu impose une stratégie individualisée. Les consignes d’une flambée ou d’une infection invasive ne se confondent pas avec celles d’une angine isolée.')),
('Le {point clé est la décision clinique autour du test}. La gorge rouge ne suffit pas et le résultat ne décide pas seul. La notice exacte doit accompagner toute prescription.',paras('Les divergences de durée entre AIPS et SSI sont signalées dans la fenêtre médicamenteuse. La réduction de l’exposition antibiotique ne doit jamais faire négliger une complication.'))]
q=[('Quel agent correspond au streptocoque A ?','Streptococcus pyogenes.'),('Centor est-il un test microbiologique ?','Non.'),('Combien de critères comporte Centor ?','Quatre.'),('Un score bas exclut-il un abcès ?','Non.'),('Quand proposer le test selon SSI ?','Quand le tableau et le score le justifient et que le résultat modifierait une décision antibiotique.'),('Faut-il cultiver systématiquement après un test négatif ?','Non, dans une forme simple selon la stratégie suisse citée.'),('Un test positif impose-t-il toujours de traiter ?','Non.'),('Quel suivi pédiatrique est proposé sans critère d’inquiétude ?','Une réévaluation à 48–72 heures, plus tôt si aggravation.'),('L’antibiotique prévient-il la glomérulonéphrite aiguë ?','Non selon la synthèse suisse citée.'),('Quel contexte change la démarche quel que soit le score ?','Un antécédent de rhumatisme articulaire aigu.'),('La suspension et les comprimés Amoxicilline Sandoz portent-ils le même numéro ?','Non :49923 pour les granulés et 49924 pour les comprimés pelliculés cités.'),('La notice citée autorise-t-elle la mononucléose ?','Non, elle la contre-indique.'),('Six jours SSI équivaut-il à dix jours AIPS ?','Non, la divergence doit être explicitée et assumée par le prescripteur.'),('L’éviction scolaire est-elle systématique ?','Non selon Pédiatrie suisse 2023 ; apprécier état général et contexte.')]
produire(2,p,q,(1,2,3,6,12),amoxicilline)

p=[
('La {mononucléose infectieuse à EBV} est un tableau lié à une infection par le virus Epstein-Barr. Elle associe souvent angine, fièvre, adénopathies et fatigue. Toutes les infections par EBV ne produisent pas ce syndrome.',paras('Le syndrome mononucléosique est une présentation clinique et biologique, pas un synonyme obligatoire d’EBV. Le cytomégalovirus, une primo-infection VIH et d’autres infections peuvent en être responsables.', 'Les sources HUG et NHS décrivent la transmission notamment par la salive. La présentation et la gravité varient avec l’âge et le terrain.')),
('Le {contexte adolescent ou jeune adulte est évocateur}. L’infection peut durer plus longtemps qu’une angine respiratoire simple. La fatigue peut persister après l’amélioration de la gorge.',paras('Le NHS décrit une maladie fréquente chez les adolescents et jeunes adultes et une amélioration habituelle en deux à quatre semaines. Une fatigue prolongée peut persister plusieurs mois chez certaines personnes.', 'Aucune incidence suisse récente de la mononucléose symptomatique n’a été trouvée dans les sources consultées. Les proportions d’infection EBV dans un syndrome mononucléosique ne sont pas transposées en prévalence de tout mal de gorge.')),
('L’{infection touche le tissu lymphoïde}. La réponse immunitaire contribue aux ganglions et à l’hypertrophie amygdalienne. L’atteinte splénique ou hépatique change les précautions.',table(['Perturbation','Recherche','Conduite'],[['Inflammation amygdalienne et ganglionnaire.','Examen de gorge et des aires ganglionnaires.','Soutien ; urgence si obstruction.'],['Augmentation de volume de la rate.','Contexte clinique et examen prudent ; imagerie si complication suspectée.','Éviter traumatismes, sport et efforts importants pendant la phase à risque.'],['Atteinte hépatique.','Symptômes et bilan hépatique selon indication.','Adapter les médicaments ; contre-indication AIPS au paracétamol cité si hépatite aiguë.']])+paras('La rate est un organe lymphoïde situé dans la partie supérieure gauche de l’abdomen. Sa fragilité lors de l’infection explique le danger d’une douleur abdominale aiguë ou d’un traumatisme.')),
('Les {complications respiratoires et spléniques sont prioritaires}. L’angine ne doit pas masquer une obstruction. Une douleur abdominale forte impose une évaluation urgente.',table(['Situation','Signe','Conduite'],[['🚩 Obstruction pharyngée.','Dyspnée, salivation, impossibilité d’avaler.','Urgence hospitalière et voies aériennes.'],['🚩 Complication splénique.','Douleur abdominale intense, malaise ou aggravation après choc.','Urgence immédiate.'],['Abcès périamygdalien.','Trismus ou asymétrie marquée.','Avis ORL ; l’EBV n’empêche pas une complication suppurative.'],['Autre syndrome mononucléosique.','Exposition sexuelle, terrain ou sérologie non compatible.','Examens adaptés plutôt qu’un diagnostic EBV par défaut.']])) ,
('L’{anamnèse recherche fatigue, ganglions et manifestations à distance}. Demander la durée des symptômes et les contacts salivaires. Identifier sports, douleurs abdominales et médicaments récents.',paras('Une fatigue majeure et des adénopathies hors du cou orientent davantage qu’un seul dépôt sur les amygdales. Interroger sur exposition sexuelle si une primo-infection VIH entre dans le diagnostic différentiel.', 'Demander prise d’amoxicilline, apparition de rash, alcool et médicaments potentiellement hépatotoxiques. Préciser les activités avec collision, chute ou port de charges afin de donner des conseils concrets.')),
('L’{examen ne se limite pas aux amygdales}. Évaluer respiration, hydratation et aires ganglionnaires. Examiner l’abdomen avec prudence selon le contexte.',paras('Inspecter l’oropharynx et comparer les côtés. Rechercher des ganglions cervicaux et à distance ; documenter une éruption et l’état général.', 'L’absence de rate palpable ne prouve pas l’absence d’atteinte splénique. Une douleur abdominale importante, une instabilité ou des signes respiratoires appellent une prise en charge urgente et non une palpation répétée.')),
('L’{approche syndromique distingue trois dimensions}. L’angine, la réaction ganglionnaire et le retentissement général ne progressent pas toujours ensemble. Les manifestations d’organe commandent le bilan.',paras('<em>7.1 — Syndrome pharyngé.</em> Douleur et hypertrophie amygdalienne, avec capacité à boire à apprécier.', '<em>7.2 — Syndrome lymphatique et général.</em> Fièvre, fatigue et ganglions, recherchés au-delà du cou.', '<em>7.3 — Atteinte d’organe.</em> Douleur abdominale, ictère, saignement ou symptômes neurologiques ne sont pas des éléments à banaliser ; orienter le bilan.')),
('Le {diagnostic associe clinique et sérologie adaptée}. Une sérologie ancienne positive n’établit pas une infection récente. L’interprétation dépend du profil et du délai.',paras('Les HUG présentent les anticorps anti-VCA de classes IgM et IgG et les anticorps anti-EBNA IgG pour caractériser l’infection. Le résultat doit être interprété par le laboratoire avec le début des symptômes et les éventuelles réactions croisées.', 'Le test à anticorps hétérophiles n’est pas retenu comme unique preuve par le support HUG consulté. Si le tableau reste évocateur malgré un premier résultat non concluant, discuter un contrôle ou une autre étiologie.')),
('Les {examens ciblent confirmation et complications}. La sérologie n’est qu’une partie du bilan. Les tests supplémentaires répondent au terrain et aux signes associés.',table(['Étape','Objectif'],[['9.a : confirmation.','Sérologie EBV interprétée avec la chronologie.'],['9.b : retentissement.','Hémogramme ou bilan hépatique si la clinique le justifie.'],['9.c : alternatives.','Recherche VIH, cytomégalovirus ou autre cause selon anamnèse et résultats.'],['9.d : complication.','Imagerie et bilan urgent si douleur abdominale, obstruction ou autre signe d’organe.']])) ,
('L’{algorithme protège respiration et rate}. La plupart des formes relèvent du soutien. Les complications modifient immédiatement le niveau de soins.',steps('Évaluer déglutition, respiration, hydratation et douleur abdominale.','Si alarme, hospitaliser selon la complication suspectée.','Si forme stable, confirmer l’hypothèse selon contexte et sérologie.','Éviter amoxicilline empirique et traitements symptomatiques contre-indiqués.','Organiser repos, suivi et reprise graduée des activités après évaluation.')),
('La {prise en charge est essentiellement symptomatique}. Les antibiotiques ne traitent pas EBV. Une éventuelle complication doit être prise en charge pour elle-même.',paras('<em>11.A — Urgence.</em> Obstruction, aphagie, déshydratation importante ou douleur abdominale aiguë imposent une évaluation hospitalière.', '<em>11.B — Soutien.</em> Repos, boissons si déglutition sûre et antalgie adaptée. @@MEDICAMENTS@@', '<em>11.C — Médicaments à éviter.</em> L’information professionnelle Amoxicilline Sandoz citée contre-indique la mononucléose. Ne pas donner un antibiotique simplement pour des exsudats. Une hépatite aiguë contre-indique le DAFALGAN décrit dans la fenêtre.', '<em>11.D — Surveillance.</em> Évaluer la récupération, la capacité à s’alimenter et la tolérance des activités. Une corticothérapie ne constitue pas un traitement automatique de toute angine EBV ; les indications de complication relèvent du spécialiste.')),
('La {prévention vise la transmission salivaire et les traumatismes spléniques}. Éviter les objets partagés portés à la bouche. Suspendre les sports et efforts importants pendant la phase symptomatique.',paras('Le NHS recommande de ne pas pratiquer d’activité intense, de sport ou de port de charges pendant la maladie. La reprise doit être individualisée avec le médecin selon l’évolution et le risque de traumatisme ; aucun délai unique n’est présenté comme garantie de sécurité.', 'L’excrétion salivaire peut persister après la guérison clinique. Expliquer les mesures d’hygiène sans promettre qu’un jour précis met fin à toute contagiosité.')),
('Le {point clé est de reconnaître une maladie au-delà de la gorge}. Une amélioration de l’angine ne signifie pas forcément une récupération complète. La rate et le foie modifient les conseils et les médicaments.',paras('Une sérologie doit répondre à une question clinique explicite. Une douleur abdominale forte ou une gêne respiratoire au cours du suivi prime sur le caractère habituellement favorable de l’infection.'))]
q=[('Un syndrome mononucléosique signifie-t-il toujours EBV ?','Non.'),('Quelle transmission est classique ?','La salive.'),('La fatigue peut-elle persister après l’angine ?','Oui.'),('Quelle douleur doit faire craindre une complication splénique ?','Une douleur abdominale importante, surtout aiguë ou avec malaise.'),('L’absence de rate palpable exclut-elle son atteinte ?','Non.'),('Les antibiotiques guérissent-ils EBV ?','Non.'),('Les exsudats imposent-ils l’amoxicilline ?','Non ; cette notice la contre-indique dans la mononucléose.'),('Un ancien profil sérologique positif prouve-t-il l’épisode actuel ?','Non.'),('Que rechercher si la sérologie ne correspond pas au tableau ?','Une autre cause ou un résultat influencé par le délai.'),('Quels anticorps présente le support HUG ?','Anti-VCA IgM/IgG et anti-EBNA IgG, interprétés selon le profil.'),('Quel médicament cité est contre-indiqué en hépatite aiguë ?','DAFALGAN selon la notice retenue.'),('Une corticothérapie est-elle automatique ?','Non.'),('La reprise sportive a-t-elle un délai universel garanti ?','Non, elle dépend d’une évaluation individuelle.'),('L’EBV exclut-il un abcès périamygdalien ?','Non.')]
produire(3,p,q,(2,3,7,9,12,13),antalgie)
